from PIL import Image
import collections
for p in ['/home/robot/captures/overview_001.jpg','/home/robot/captures/overview_004.jpg']:
    im=Image.open(p).convert('RGB')
    W,H=im.size
    pix=im.load()
    # detect yellowish guard ring: R>150,G>120,B<120 maybe
    ys=[]
    for y in range(H):
        for x in range(W):
            r,g,b=pix[x,y]
            if r>150 and g>120 and b<120:
                ys.append((x,y,r,g,b))
    print(p,'yellow pixels',len(ys))
    if ys:
        xs=[p[0] for p in ys]; yy=[p[1] for p in ys]
        print('bbox x',min(xs),max(xs),'y',min(yy),max(yy))
    # print a coarse mask as ascii with + for yellow
    mask=[[' ' for _ in range(80)] for _ in range(60)]
    for x,y,r,g,b in ys:
        X=x*80//W; Y=y*60//H
        mask[Y][X]='+'
    for row in mask: print(''.join(row))
PY"}

