import cv2, numpy as np
for p in ['/home/robot/captures/side_005.jpg','/home/robot/captures/side_003.jpg','/home/robot/captures/side_002.jpg']:
    img=cv2.imread(p)
    gray=cv2.cvtColor(img,cv2.COLOR_BGR2GRAY)
    print('\n===',p,'===')
    for x1,x2 in [(220,400),(240,400),(250,390),(260,380)]:
        crop=gray[:,x1:x2]
        gy=cv2.Sobel(crop,cv2.CV_64F,0,1,ksize=3)
        prof=cv2.GaussianBlur(np.sum(np.abs(gy),axis=1),(1,5),3).ravel()
        peaks=[]
        for i in range(180,400):
            if prof[i]>50 and prof[i]>=prof[i-1] and prof[i]>=prof[i+1]:
                peaks.append((i,float(prof[i])))
        supp=[]
        for i,v in peaks:
            if all(abs(i-s)>4 for s,vv in supp):
                supp.append((i,v))
        supp=sorted(supp,key=lambda x:-x[1])[:20]
        supp=sorted(supp,key=lambda x:x[0])
        print('x',x1,x2,'peaks',[(i,round(v,1)) for i,v in supp])
PY"}

